        {
          "text": "[الزلزلة: 7–8]",
          "color": "5B626B",
          "colorTheme": null,
          "bold": false
        },
        {
          "text": "، ويتمنى صاحب السوء لو أن بينه وبين عمله أمدا بعيدا: ",
          "color": "000000",
          "colorTheme": null,
          "bold": false
